+
+func sendMetrics(ctx context.Context, metrics *vegeta.Metrics, ch chan<- *Metrics) {
+	// TODO: Make the interval changeable.
+	ticker := time.NewTicker(250 * time.Millisecond)
+	defer ticker.Stop()
+
+	for {
+		select {
+		case <-ctx.Done():
+			return
+		case <-ticker.C:
+			ch <- newMetrics(metrics)
+		}
+	}
 }
